#!/usr/bin/env python3\n\n# ============================================================================\n# AUDIOBOOK STUDIO - TTS ENGINE\n# ============================================================================\n# FastAPI application for text-to-speech audio generation using Coqui TTS\n# ============================================================================\n\nimport os\nimport logging\nfrom fastapi import FastAPI, HTTPException\nfrom pydantic import BaseModel\nimport torch\nfrom TTS.api import TTS\n\n# ============================================================================\n# CONFIGURATION\n# ============================================================================\n\nLOG_LEVEL = os.getenv('FASTAPI_LOG_LEVEL', 'info').upper()\nTTS_MODEL = os.getenv('TTS_MODEL', 'tts_models/en/ljspeech/glow-tts')\nTTS_DEVICE = os.getenv('TTS_DEVICE', 'auto')\nTTS_CACHE_DIR = os.getenv('TTS_CACHE_DIR', '/app/models')\nFASTAPI_HOST = os.getenv('FASTAPI_HOST', '0.0.0.0')\nFASTAPI_PORT = int(os.getenv('FASTAPI_PORT', 5000))\nFASTAPI_WORKERS = int(os.getenv('FASTAPI_WORKERS', 2))\n\n# ============================================================================\n# LOGGING\n# ============================================================================\n\nlogging.basicConfig(\n    level=LOG_LEVEL,\n    format='[%(asctime)s] %(levelname)s - %(name)s - %(message)s'\n)\nlogger = logging.getLogger(__name__)\n\n# ============================================================================\n# FASTAPI APP\n# ============================================================================\n\napp = FastAPI(\n    title=\"Audiobook Studio - TTS Engine\",\n    description=\"Text-to-speech audio generation service\",\n    version=\"1.0.0\"\n)\n\n# ============================================================================\n# TTS INITIALIZATION\n# ============================================================================\n\ntts_instance = None\n\ndef initialize_tts():\n    \"\"\"Initialize TTS engine\"\"\"\n    global tts_instance\n    try:\n        logger.info(f\"Initializing TTS with model: {TTS_MODEL}\")\n        logger.info(f\"Device: {TTS_DEVICE}\")\n        \n        # Determine device\n        if TTS_DEVICE == 'auto':\n            device = 'cuda' if torch.cuda.is_available() else 'cpu'\n        else:\n            device = TTS_DEVICE\n        \n        logger.info(f\"Using device: {device}\")\n        \n        # Initialize TTS\n        tts_instance = TTS(\n            model_name=TTS_MODEL,\n            gpu=(device == 'cuda'),\n            progress_bar=False\n        )\n        \n        logger.info(\"TTS engine initialized successfully\")\n        return True\n    except Exception as e:\n        logger.error(f\"Failed to initialize TTS: {str(e)}\")\n        return False\n\n# ============================================================================\n# MODELS\n# ============================================================================\n\nclass GenerateRequest(BaseModel):\n    \"\"\"Text-to-speech generation request\"\"\"\n    text: str\n    voice_id: str = \"default\"\n    speed: float = 1.0\n    pitch: float = 1.0\n\nclass HealthResponse(BaseModel):\n    \"\"\"Health check response\"\"\"\n    status: str\n    device: str\n    model: str\n    gpu_available: bool\n\n# ============================================================================\n# ROUTES\n# ============================================================================\n\n@app.on_event(\"startup\")\nasync def startup_event():\n    \"\"\"Initialize TTS on startup\"\"\"\n    logger.info(\"Starting TTS engine...\")\n    initialize_tts()\n\n@app.get(\"/health\", response_model=HealthResponse)\nasync def health_check():\n    \"\"\"Health check endpoint\"\"\"\n    if tts_instance is None:\n        raise HTTPException(status_code=503, detail=\"TTS engine not initialized\")\n    \n    return HealthResponse(\n        status=\"healthy\",\n        device=\"cuda\" if torch.cuda.is_available() else \"cpu\",\n        model=TTS_MODEL,\n        gpu_available=torch.cuda.is_available()\n    )\n\n@app.post(\"/generate\")\nasync def generate_audio(request: GenerateRequest):\n    \"\"\"Generate audio from text\"\"\"\n    if tts_instance is None:\n        raise HTTPException(status_code=503, detail=\"TTS engine not initialized\")\n    \n    try:\n        logger.info(f\"Generating audio for text: {request.text[:50]}...\")\n        \n        # Generate audio\n        audio = tts_instance.tts(request.text)\n        \n        logger.info(\"Audio generated successfully\")\n        \n        # Return audio as bytes\n        return {\"status\": \"success\", \"audio\": audio}\n    except Exception as e:\n        logger.error(f\"Generation failed: {str(e)}\")\n        raise HTTPException(status_code=500, detail=str(e))\n\n@app.get(\"/\")\nasync def root():\n    \"\"\"Root endpoint\"\"\"\n    return {\n        \"name\": \"Audiobook Studio - TTS Engine\",\n        \"version\": \"1.0.0\",\n        \"status\": \"running\",\n        \"endpoints\": {\n            \"health\": \"/health\",\n            \"generate\": \"/generate\",\n            \"docs\": \"/docs\"\n        }\n    }\n\n# ============================================================================\n# MAIN\n# ============================================================================\n\nif __name__ == \"__main__\":\n    import uvicorn\n    \n    logger.info(f\"Starting TTS engine on {FASTAPI_HOST}:{FASTAPI_PORT}\")\n    logger.info(f\"Workers: {FASTAPI_WORKERS}\")\n    \n    uvicorn.run(\n        \"app:app\",\n        host=FASTAPI_HOST,\n        port=FASTAPI_PORT,\n        workers=FASTAPI_WORKERS,\n        reload=False,\n        log_level=LOG_LEVEL.lower()\n    )\n
